//! Colours generated by pywal / wallust (`~/.cache/wal/colors.json`).

use std::path::{Path, PathBuf};

use serde::Deserialize;

use super::palette::{Color, Palette};
use crate::util::xdg;

#[derive(Deserialize)]
struct WalFile {
    special: WalSpecial,
    colors: std::collections::HashMap<String, String>,
}

#[derive(Deserialize)]
struct WalSpecial {
    background: String,
    foreground: String,
}

/// `$XDG_CACHE_HOME/wal/colors.json`.
pub fn default_path() -> PathBuf {
    std::env::var_os("XDG_CACHE_HOME")
        .map(PathBuf::from)
        .filter(|p| p.is_absolute())
        .unwrap_or_else(|| xdg::home_dir().join(".cache"))
        .join("wal/colors.json")
}

fn mix(a: Color, b: Color, t: f32) -> Color {
    let m = |x: u8, y: u8| (x as f32 + (y as f32 - x as f32) * t).round() as u8;
    Color(m(a.0, b.0), m(a.1, b.1), m(a.2, b.2))
}

pub fn load(path: &Path) -> Option<Palette> {
    let file: WalFile = serde_json::from_str(&std::fs::read_to_string(path).ok()?).ok()?;
    let color = |n: u8| file.colors.get(&format!("color{n}")).and_then(|c| Color::parse(c));
    let background = Color::parse(&file.special.background)?;
    let text = Color::parse(&file.special.foreground)?;
    Some(Palette {
        name: "pywal".into(),
        dark: background.luminance() < text.luminance(),
        background,
        surface: mix(background, text, 0.12),
        surface_alt: mix(background, text, 0.2),
        border: mix(background, text, 0.3),
        text,
        text_muted: mix(text, background, 0.3),
        accent: color(4)?,
        red: color(1)?,
        green: color(2)?,
        yellow: color(3)?,
        blue: color(4)?,
        magenta: color(5)?,
        cyan: color(6)?,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_wal_colors() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("colors.json");
        let colors: String = (0..16)
            .map(|i| format!("\"color{i}\": \"#{:02x}{:02x}{:02x}\",", i * 10, i * 10, i * 10))
            .collect();
        std::fs::write(
            &path,
            format!(r##"{{"special": {{"background": "#101010", "foreground": "#f0f0f0", "cursor": "#ffffff"}}, "colors": {{ {} }} }}"##, colors.trim_end_matches(',')),
        )
        .unwrap();
        let palette = load(&path).unwrap();
        assert!(palette.dark);
        assert_eq!(palette.blue, Color(40, 40, 40));
        assert_eq!(palette.surface, mix(Color(16, 16, 16), Color(240, 240, 240), 0.12));
    }
}
